"""Finalize the metadata-only cohort qualification record and manifest."""
from support import *
import re,h5py

def main():
 assert not (A/'C7A_SPEC_LOCK.json').exists();audit=json.loads((A/'logs/HER2ST_METADATA_AUDIT.json').read_text());rows=[];intersections=[]
 for s,r in zip(SAMPLES,audit['samples']):
  p=CACHE/(s+'.jpg');src=next(x for x in json.loads((OUT/'raw/HER2ST_metadata.json').read_text())['files'] if x['key']=='images.zip');hashes=json.loads((ROOT/'reports/C0/C0_DOWNLOADS.json').read_text())['files'];assert sha(p) not in {x['sha256'] for x in hashes}
  row={'dataset_id':'HER2ST','study_source':'https://doi.org/10.1038/s41467-021-26271-2; https://zenodo.org/records/4751624','patient_id':r['patient_id'],'sample_id':s,'disease_tissue':'HER2-positive breast cancer','platform':'Spatial Transcriptomics sequencing; 100um capture spots / 200um pitch','num_locations':r['num_locations'],'num_assay_genes':r['num_assay_genes'],'num_overlap_S2_50':r['overlaps']['S2-50'],'num_overlap_S2_250':r['overlaps']['S2-250'],'num_overlap_S2_280':r['overlaps']['S2-280'],'image_resolution':r['mpp'],'coordinate_available':True,'patient_metadata_available':True,'duplicate_check_pass':True,'qualification_status':'PASS_EXTERNAL_DATASET_QUALIFICATION','exclusion_reason':'','primary_common_genes':40,'secondary_common_genes':226};rows.append(row)
  for panel in ['S2-50','S2-250','S2-280']:
   for pos,g in enumerate(ORIGINAL[panel]):intersections.append({'dataset_id':'HER2ST','sample_id':s,'panel':panel,'frozen_gene_order':pos,'gene':g,'available':g in audit['gene_headers'][s],'included_in_evaluation':g in panels().get(panel,[]),'reason':'shared exact-symbol intersection' if g in panels().get(panel,[]) else ('optional panel omitted' if panel=='S2-250' else 'absent in at least one selected external section; no replacement')})
 for sample in ['GSM9509172','GSM9509160','GSM9509170','GSM9509165']:
  f=next((OUT/'raw').glob(sample+'*cell_feature_matrix.h5'))
  with h5py.File(f) as h:genes=h['matrix/features/name'][:].astype(str);ng=int((h['matrix/features/feature_type'][:].astype(str)=='Gene Expression').sum());cells=len(h['matrix/barcodes'])
  text=(OUT/'raw'/(sample+'.txt')).read_text();pat=re.search(r'patient \((B\d+)\)',text).group(1)
  rows.append({'dataset_id':'GSE311609','study_source':'https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE311609','patient_id':pat,'sample_id':sample,'disease_tissue':'breast cancer','platform':'Xenium breast 280-gene panel','num_locations':None,'num_assay_genes':ng,'num_overlap_S2_50':50,'num_overlap_S2_250':250,'num_overlap_S2_280':280,'image_resolution':.4422626155411083,'coordinate_available':True,'patient_metadata_available':True,'duplicate_check_pass':True,'qualification_status':'NOT_QUALIFIED_REGISTRATION','exclusion_reason':'Supplied H&E/DAPI are unregistered; public source references private transform files. Image-only attempts did not demonstrate reliable spot-scale registration. Counts never evaluated.','source_cell_count_not_model_locations':cells})
 prime=json.loads((OUT/'raw/prime_gene_panel.json').read_text())['payload'];pg={x['type']['data']['name'] for x in prime['targets'] if x['type']['descriptor']=='gene'}
 rows.append({'dataset_id':'Xenium_Prime_Breast_Cancer_FFPE','study_source':'https://www.10xgenomics.com/datasets/xenium-prime-ffpe-human-breast-cancer','patient_id':'single donor; source study release 2024-10-24','sample_id':'Xenium_Prime_Breast_Cancer_FFPE','disease_tissue':'breast cancer','platform':'Xenium Prime 5K+100','num_assay_genes':len(pg),'num_overlap_S2_50':len(set(ORIGINAL['S2-50'])&pg),'num_overlap_S2_250':len(set(ORIGINAL['S2-250'])&pg),'num_overlap_S2_280':len(set(ORIGINAL['S2-280'])&pg),'coordinate_available':True,'patient_metadata_available':False,'duplicate_check_pass':None,'qualification_status':'EXCLUDED_INSUFFICIENT_PRIMARY_OVERLAP','exclusion_reason':'30/50 (60%) exact primary symbols; below fixed 80% threshold. No synonym substitution or threshold reduction; donor independence need not be decided after exclusion.'})
 meta=pd.read_csv(ROOT/'data/raw/HEST_v1_1_0.csv');breast=meta[(meta.organ=='Breast')&(meta.st_technology=='Xenium')]
 for _,r in breast.iterrows():
  dev=r.id in parent.IDS;reason='Development patient/sample' if dev else ('Same development patient' if r.id in ['TENX98','TENX97','NCBI784'] else 'Same source release/study as development; not an independent cohort')
  rows.append({'dataset_id':'HEST_v1_1_0','study_source':str(r.study_link)+'; '+str(r.download_page_link1),'patient_id':r.patient,'sample_id':r.id,'disease_tissue':r.organ+' '+r.disease_state,'platform':r.st_technology,'coordinate_available':True,'patient_metadata_available':True,'duplicate_check_pass':False if dev or r.id in ['TENX98','TENX97','NCBI784'] else None,'qualification_status':'EXCLUDED_DEVELOPMENT_OR_RELATED_COHORT','exclusion_reason':reason})
 fields=['dataset_id','study_source','patient_id','sample_id','disease_tissue','platform','num_locations','num_assay_genes','num_overlap_S2_50','num_overlap_S2_250','num_overlap_S2_280','image_resolution','coordinate_available','patient_metadata_available','duplicate_check_pass','qualification_status','exclusion_reason','primary_common_genes','secondary_common_genes','source_cell_count_not_model_locations'];frame=pd.DataFrame(rows).reindex(columns=fields);frame.to_csv(A/'C7A_EXTERNAL_DATASET_MANIFEST.csv',index=False);frame.to_csv(OUT/'C7A_EXTERNAL_DATASET_MANIFEST.csv',index=False);pd.DataFrame(intersections).to_csv(A/'C7A_GENE_INTERSECTION.csv',index=False)
 stats={'status':'PASS_EXTERNAL_DATASET_QUALIFICATION','cohort':'HER2ST','patients':8,'locations':sum(r['num_locations'] for r in audit['samples']),'S2_50_retained':40,'S2_280_retained':226,'expression_values_used_for_qualification':False,'image_coordinate_visual_review':'PASS: all eight supplied coordinate overlays lie on their corresponding tissue; estimated mpp 0.686–0.917, mapping residual <0.006 pixels. Does not certify cellular registration.','source_independence':'Independent 2021 Swedish HER2ST study, distinct patient IDs A–H, assay and raw assets; no C0–C6 development sample used.','counts_contract':'Published integer UMI counts will be checked after freeze; no cross-platform harmonization fit.'};dump(A/'C7A_STATUS.json',stats)
 report=f'''# C7A — External cohort qualification\n\nStatus: **PASS_EXTERNAL_DATASET_QUALIFICATION**. Eight independent HER2ST patients, one first-numbered section each (A1–H1), {stats['locations']:,} selected capture locations. No external expression values or reconstruction outcomes informed qualification.\n\nThe [source study](https://doi.org/10.1038/s41467-021-26271-2) and [public source deposit](https://zenodo.org/records/4751624) identify eight breast-cancer patients. Its 2021 Swedish cohort, patient identities and sequencing-ST assets are independent of the four development patients. The published source archive MD5 values are checked alongside local SHA-256 records. Barcode keys link supplied coordinates, count-matrix row identifiers and patch order.\n\n## Cohort and preprocessing\n\nFirst-numbered section of **each** source patient was selected before expression values were read. Serial sections are not additional patients. Individual S2-50 availability is 45–46 genes, but the same common **40/50** genes (80%) are evaluated for every patient. S2-280 uses the shared **226/280** genes (80.7%). No aliases, replacements or outcome-based selection. S2-250 is optional and omitted. The [exact intersection](C7A_GENE_INTERSECTION.csv) includes every original panel gene and exclusion reason.\n\nH&E uses a 112 µm square, 224 RGB pixels, the frozen C0 ResNet18 weights and official transform. ResNet18 is the predeclared primary encoder; Phikon is not additionally evaluated. E0 averages the three frozen primary C4 D1 heads; E1 and E2 retain C5 validation-selected interpolation and fusion parameters for each original panel/regime; E3 retains exact C5 B4 weights and image PCA, with independent gene heads restricted to retained genes. No model is fit.\n\nThe target interface remains log1p(integer counts) standardized using C0 training-only gene means/SDs. This is a **cross-platform** zero-shot test: sequencing capture spots are 100 µm diameter with 200 µm spacing, whereas development pooled Xenium transcripts in 100 µm squares. Capture efficiency, capture area, depth, preparation and image resolution can shift distributions. They are not corrected from external labels. Compatibility here means executable frozen count/image model inputs, not calibrated cross-assay abundance equivalence. Integer-count validation is mandatory after lock.\n\nPublished selected spots and gene columns inherit upstream source filtering. The qualification reader parses only gene headers and spot identifiers; numeric count fields are discarded. No external expression matrix has been loaded. Source H&E annotation labels are not used.\n\n![Supplied coordinate QA](logs/HER2ST_ALIGNMENT_QA.png)\n\n## Alternatives and exclusions\n\nDevelopment/related HEST Xenium samples were excluded by patient and source; the complete HEST asset repository returned HTTP 401 and no authorized Hugging Face credential was configured. This does not mean no independent public dataset exists.\n\nThe independent [GSE311609](https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE311609) four-donor pilot B1–B4 had 50/50 and 280/280 overlap but no verified public H&E-to-DAPI transforms. Its source notebook refers to private transform paths. SIFT, tissue-outline and affine intensity methods were examined using images only; high silhouette agreement did not establish reliable local correspondence. These exploratory image-registration diagnostics are not certified target-registration errors, and are not validation results. The cohort was not admitted to C7B. No molecular counts were evaluated.\n\nThe [Xenium Prime breast release](https://www.10xgenomics.com/datasets/xenium-prime-ffpe-human-breast-cancer) had only 30/50 primary-gene exact-symbol overlap and was excluded at the fixed 80% threshold. Its low-resolution tutorial derivative was not counted as another cohort or patient. Source run-summary metadata was inspected but no expression matrix or performance was evaluated.\n\n## Frozen evaluation design\n\nS2-50 common 40 genes is primary; S2-280 common 226 is secondary, not whole-transcriptome validation. Budgets 10/20/40%, ten random seeds and deterministic spatial FPS. V1 scores all unobserved tissue. V2 uses three coordinate-defined 40% unavailable regions, fixed across budgets and policies, and samples outside them. Regions are centered at 25/50/75% along the tissue's first spatial principal axis. All unobserved labels are removed before model inputs.\n\nQuantitative patient-level decision rules, distance bins, controls and six display genes are fixed in [protocol.json](../configs/protocol.json). All 352 trajectories must be hashed before external-label access. Qualifying a dataset is not a claim that C5 generalizes. C7C/adaptation are not planned.\n'''
 (A/'C7A_REPORT.md').write_text(report)
 print(stats)
if __name__=='__main__':main()
